Authorization: Bearer {{token}}
Content-Type: application/json
Accept: application/json

{
  "session": {
    "model": "gpt-live-1",
    "instructions": "string",
    "audio": {
      "output": {}
    },
    "delegation": {
      "type": "client"
    },
    "store": true,
    "input": [
      {}
    ],
    "client": {
      "data_channel": {}
    }
  },
  "transport": {
    "type": "webrtc",
    "sdp": "string"
  }
}

